// HooCode teaser v2: the one shared timeline for all three aspects.
// Times come from beats.js (generated by build.py from the edit; the SFX in events.json use the
// same numbers). Layout comes from CSS; footage crops are computed here from the window's size.
// Everything is a function of timeline time: no Date, no random, no media play/pause/seek.
(function () {
  var B = window.TEASER_BEATS;
  var stage = document.getElementById("stage");
  var $ = function (s, root) { return (root || document).querySelector(s); };
  var $$ = function (s, root) { return Array.prototype.slice.call((root || document).querySelectorAll(s)); };

  var EXPO = "expo.out";          // cubic-bezier(0.16, 1, 0.3, 1)
  var tl = gsap.timeline({ paused: true });
  window.__timelines = window.__timelines || {};
  window.__timelines["hoocode-teaser"] = tl;

  // ---------------------------------------------------------------- footage geometry (4K px)
  // xterm grid: 117 x 32 cells of 29 x 65 px, origin (224, 40) in the 3840x2160 frame.
  var GX = 224, GY = 40, CW = 29, CH = 65, SRC_H = 2160;
  function cells(c0, c1, r0, r1) {           // inclusive cell range -> rect
    return { x0: GX + c0 * CW, x1: GX + (c1 + 1) * CW, y0: GY + r0 * CH, y1: GY + (r1 + 1) * CH };
  }
  // Each shot: crop width in 4K px per aspect (the window shows this much of the frame's width),
  // crop left edge x, vertical placement (bottom edge or centre), bracket target cells.
  // 9:16 pushes in further on the key strings so they render about 36 px tall on a phone.
  var ASPECT = stage.className;
  var SHOTS = {
    plans: { w: { a9x16: 1570, a1x1: 1570, a16x9: 1680 }, x: 232, bottom: 2160,
             target: cells(2, 51, 25, 28) },                         // task panel: the 4-item plan
    asks:  { w: { a9x16: 1320, a1x1: 1570, a16x9: 1680 }, x: 180,
             bottom: { a9x16: 2330, a1x1: 2210, a16x9: 2210 },
             target: cells(0, 20, 27, 28) },                         // ◎ CLEARANCE NEEDED / Edit src/main.rs
    tests: { w: { a9x16: 1320, a1x1: 1400, a16x9: 1500 }, x: 200, cy: 950,
             red: cells(8, 35, 10, 10),                              // "Command exited with code 101" (5.0-5.467)
             target: cells(8, 32, 16, 16),                           // "test result: ok. 2 passed" (6.0)
             end: { zoom: 1.15 } },                                  // push 5.6-6.0, left edge fixed, on the result row
    lands: { w: { a9x16: 1320, a1x1: 1570, a16x9: 1680 }, x: 232, bottom: 2190,
             target: cells(2, 9, 23, 23) }                           // ● LANDED (the transcript landing line)
  };
  function pick(v) { return (v !== null && typeof v === "object") ? v[ASPECT] : v; }

  var inner = $("#win-inner");
  var IW = inner.clientWidth, IH = inner.clientHeight;
  var PADX = 14, PADY = 5;                    // bracket padding, px (rows sit close together)

  function cropTop(shot, s) {
    var h = IH / s, bottom = pick(shot.bottom);
    var top = bottom !== undefined ? bottom - h : shot.cy - h / 2;
    return Math.min(Math.max(top, -60), SRC_H + 200 - h);
  }
  function camVars(left, top, s) { return { x: -left * s, y: -top * s, scale: s }; }

  // ---------------------------------------------------------------- scenes
  // Zero-length sets sit EPS before their beat, so a seek to the beat's exact frame time always
  // includes them (float time can land a hair early).
  var EPS = 0.005;
  function cut(sel, t0, t1) {
    tl.set(sel, { autoAlpha: 1 }, Math.max(0, t0 - EPS));
    if (t1 !== undefined) tl.set(sel, { autoAlpha: 0 }, t1 - EPS);
  }
  cut("#sc-owl", 0, 1.0);          // visible from frame 0 by CSS (poster); the set keeps seeks exact
  cut("#sc-work", 1.0, 9.0);
  cut("#sc-spark", 9.0, 11.0);
  cut("#sc-lock", 11.0);

  // ---------------------------------------------------------------- 0.0-1.0 owl
  tl.fromTo("#owl-group", { scale: 1 }, { scale: 1.035, duration: 1.0, ease: "none", transformOrigin: "50% 50%" }, 0);
  // Eyes: #27272A on the poster, light #00F0FF on beat 2 (0.5), with the blip.
  tl.set("#owl .owl-eyes", { fill: "#00F0FF", filter: "drop-shadow(0 0 18px rgba(0,240,255,0.55))" }, B.eyes - EPS);
  tl.fromTo("#owl .owl-eyes", { filter: "drop-shadow(0 0 18px rgba(0,240,255,0.55))" },
    { filter: "drop-shadow(0 0 8px rgba(0,240,255,0.40))", duration: 0.4, ease: "power2.out", immediateRender: false }, B.eyes);

  // ---------------------------------------------------------------- 1.0-9.0 the four acts
  function placeBrackets(el, t, cam) {
    gsap.set(el, { left: (t.x0 - cam.left) * cam.s - PADX, top: (t.y0 - cam.top) * cam.s - PADY,
                   width: (t.x1 - t.x0) * cam.s + 2 * PADX, height: (t.y1 - t.y0) * cam.s + 2 * PADY });
  }
  function snap(el, t0, t1) {                 // brackets snap in (scale 1.08 -> 1.0, 0.15 s) and cut out
    tl.set(el, { autoAlpha: 1 }, t0 - EPS);
    tl.fromTo(el, { scale: 1.08, transformOrigin: "50% 50%" },
      { scale: 1, duration: 0.15, ease: EXPO, immediateRender: false }, t0);
    if (t1 !== undefined) tl.set(el, { autoAlpha: 0 }, t1 - EPS);
  }

  B.acts.forEach(function (a) {
    var shot = SHOTS[a.id];
    var act = $("#act-" + a.id);
    var cam = $(".cam", act), push = $(".push", act), br = $(".brackets", act);
    var S = IW / pick(shot.w);                // footage scale in the window
    var top = cropTop(shot, S);
    var t = shot.target;

    // Camera: footage scaled into the window, crop's top-left at the window's top-left.
    var cam0 = { left: shot.x, top: top, s: S };
    var cam1 = cam0;                         // the landed camera (tests: after the push)
    if (shot.end) {                          // zoom about (crop left edge, target row): the left edge stays put
      var s1 = S * shot.end.zoom, ay = (t.y0 + t.y1) / 2;
      cam1 = { left: shot.x, top: ay - (ay - top) * S / s1, s: s1 };
    }
    gsap.set(cam, camVars(cam0.left, cam0.top, cam0.s));
    placeBrackets(br, t, cam1);

    // Hard cuts on the downbeat: verb, label, footage act.
    cut(act, a.start, a.end);
    cut("#step-" + a.id, a.start, a.end);
    var verb = "#verb-" + a.id;
    // Slam: on screen from the downbeat frame itself, scale 1.12 -> 1.0 (0.25 s expo.out).
    tl.set(verb, { autoAlpha: 1 }, a.start - EPS);
    tl.fromTo(verb, { scale: 1.12 }, { scale: 1, duration: 0.25, ease: EXPO, immediateRender: false }, a.start);
    tl.set(verb, { autoAlpha: 0 }, a.end - EPS);

    // Punch-in: cut in at 0.94 and push to 1.0, landing on beat 2 (brackets ride inside the push).
    var foc = shot.red || t;
    var fx = ((foc.x0 + foc.x1) / 2 - shot.x) * S, fy = ((foc.y0 + foc.y1) / 2 - top) * S;
    tl.fromTo(push, { scale: 0.94, transformOrigin: fx + "px " + fy + "px" },
      { scale: 1, duration: 0.5, ease: "power3.out" }, a.start);

    if (shot.end) {                          // tests: push 5.6-6.0 onto the passing result, land on 6.0
      tl.fromTo(cam, camVars(cam0.left, cam0.top, cam0.s),
        Object.assign(camVars(cam1.left, cam1.top, cam1.s), { duration: 0.4, ease: "power3.inOut" }), 5.6);
    }
    if (shot.red) {                          // tests: brackets on the red evidence until the re-run lands
      var red = br.cloneNode(true);
      red.classList.add("brackets-red");
      push.appendChild(red);
      placeBrackets(red, shot.red, cam0);
      snap(red, a.start, B.exit0_film);
    }
    // Brackets snap on the landing beat.
    var land = { plans: 1.5, asks: 3.5, tests: 6.0, lands: 7.5 }[a.id];
    snap(br, land, { asks: 4.6 }[a.id]);     // card 1 leaves the screen at Y1 (4.6)
  });

  // Status chip (tests): `exit 101` (dim) over the red run; flips to `exit 0 · 2 passed` (signal,
  // diamond pop) on the frame the re-run lands (B.exit0_film, glitch tick).
  var G = B.exit0_film;
  cut("#status", 5.0, 7.0);
  tl.set("#status .st-ok", { autoAlpha: 0 }, 0);
  tl.set("#status .st-red", { autoAlpha: 0 }, G - EPS);
  tl.set("#status .st-ok", { autoAlpha: 1 }, G - EPS);
  tl.fromTo("#status", { scale: 1.12, transformOrigin: "70% 50%" },
    { scale: 1, duration: 0.25, ease: EXPO, immediateRender: false }, 5.0);
  tl.fromTo("#status", { scale: 1.12 }, { scale: 1, duration: 0.25, ease: EXPO, immediateRender: false }, G);
  tl.fromTo("#status .st-dot-ok", { scale: 0, transformOrigin: "50% 50%" },
    { keyframes: [{ scale: 1.18, duration: 0.18, ease: "power2.out" }, { scale: 1, duration: 0.12, ease: "power2.inOut" }] }, G);

  // Keycap: y go, once at 4.5 (key-press + spark-micro).
  tl.set("#keycap", { autoAlpha: 1 }, B.keycap - EPS);
  tl.fromTo("#keycap", { scale: 1.12, transformOrigin: "70% 50%" },
    { scale: 1, duration: 0.25, ease: EXPO, immediateRender: false }, B.keycap);
  tl.fromTo("#keycap .kc-key", { scale: 0.86, y: 4 }, { scale: 1, y: 0, duration: 0.2, ease: "power2.out" }, B.keycap);
  tl.fromTo("#keycap .kc-spark", { scale: 0, opacity: 1, transformOrigin: "50% 50%" },
    { keyframes: [{ scale: 1.18, duration: 0.18, ease: "power2.out" }, { scale: 1, duration: 0.12, ease: "power2.inOut" }] }, B.keycap);
  tl.to("#keycap .kc-spark", { opacity: 0, duration: 0.25, ease: "power2.in" }, B.keycap + 0.35);
  tl.set("#keycap", { autoAlpha: 0 }, 5.0 - EPS);

  // ---------------------------------------------------------------- 9.0-11.0 spark
  var arcs = $$("#symbol .sy-arc");
  arcs.forEach(function (p) {
    var L = p.getTotalLength();
    gsap.set(p, { strokeDasharray: L, strokeDashoffset: L });
    tl.to(p, { strokeDashoffset: 0, duration: 0.35, ease: "power2.out" }, B.spark + 0.05);
  });
  tl.fromTo("#symbol .sy-spark", { scale: 0, transformOrigin: "50% 50%" },
    { scale: 1, duration: 0.3, ease: "back.out(2.2)" }, B.spark);
  // Spark keyframes: 0 -> 1.18 -> 1.0 is back.out(2.2)'s overshoot; glow 0 -> 24 -> 8 px on the diamond only.
  tl.fromTo("#symbol .sy-spark", { filter: "drop-shadow(0 0 0px rgba(0,240,255,0))" },
    { keyframes: [{ filter: "drop-shadow(0 0 24px rgba(0,240,255,0.40))", duration: 0.12, ease: "power2.out" },
                  { filter: "drop-shadow(0 0 8px rgba(0,240,255,0.40))", duration: 0.5, ease: "power2.out" }] }, B.spark);
  tl.fromTo("#symbol-box", { scale: 1 }, { scale: 1.03, duration: 2.0, ease: "none", transformOrigin: "50% 50%" }, B.spark);
  tl.fromTo("#tagline", { autoAlpha: 0, y: 28 }, { autoAlpha: 1, y: 0, duration: 0.45, ease: EXPO }, B.tagline);

  // ---------------------------------------------------------------- 11.0-15.0 lockup + end card
  // Cut in on the downbeat with the mark drawn (h, nodes); the diamond sparks small (no sting here),
  // the signal arc draws, the divider and `code` fade up within the first beat.
  var L0 = B.lockup;
  tl.fromTo("#lockup .lk-spark", { scale: 0.4, transformOrigin: "50% 50%" },
    { scale: 1, duration: 0.3, ease: "back.out(2.2)", immediateRender: false }, L0);
  $$("#lockup .lk-arc").forEach(function (el) {
    var L = el.getTotalLength();
    gsap.set(el, { strokeDasharray: L + 1, strokeDashoffset: L + 1 });
    tl.to(el, { strokeDashoffset: 0, duration: 0.25, ease: "power2.out" }, L0);
  });
  tl.fromTo("#lockup .lk-div", { opacity: 0 }, { opacity: 1, duration: 0.2, ease: "none" }, L0 + 0.05);
  tl.fromTo("#lockup .lk-code", { opacity: 0, y: 5 }, { opacity: 1, y: 0, duration: 0.4, ease: EXPO }, L0 + 0.05);
  // Cursor: on for a beat, off for a beat, phase-locked to the grid; solid from 14.0.
  tl.set("#lk-cursor", { opacity: 0 }, 0);
  // (It rests while the install line types, 12.0-13.0: one cyan cursor on screen at a time.)
  for (var c = L0 + 0.5; c < B.cursor_solid; c += 1.0) {
    if (c > B.install_frames[0] / B.fps - 0.2 && c < B.end) continue;
    tl.set("#lk-cursor", { opacity: 1 }, c - EPS);
    tl.set("#lk-cursor", { opacity: 0 }, c + 0.5 - EPS);
  }
  tl.set("#lk-cursor", { opacity: 1 }, B.cursor_solid - EPS);
  tl.fromTo("#lockup-box", { scale: 1 }, { scale: 1.02, duration: 4.0, ease: "none", transformOrigin: "50% 50%" }, L0);

  tl.fromTo("#subline", { autoAlpha: 0, y: 20 }, { autoAlpha: 1, y: 0, duration: 0.45, ease: EXPO }, B.subline);

  // Install line: box at 12.0, one char per frame from beats.js (the same frames as the key ticks).
  var t0 = B.install_frames[0] / B.fps;
  tl.fromTo("#install", { autoAlpha: 0 }, { autoAlpha: 1, duration: 0.1, ease: "none" }, t0 - 0.1);
  tl.set("#tcursor", { opacity: 1 }, t0 - EPS);
  $$("#install .ch").forEach(function (el, k) {
    tl.set(el, { display: "inline" }, B.install_frames[k] / B.fps - EPS);
  });
  tl.set("#tcursor", { opacity: 0 }, B.end - EPS);

  // 13.0 end card: npm / pip + version, diamond pulse (spark-micro).
  tl.fromTo(["#alt", "#version"], { autoAlpha: 0 }, { autoAlpha: 1, duration: 0.3, ease: "none" }, B.end - EPS);
  tl.to("#lockup .lk-spark", { keyframes: [{ scale: 1.35, duration: 0.12, ease: "power2.out" },
                                            { scale: 1, duration: 0.25, ease: "power2.inOut" }] }, B.end);

  // Hold to the end.
  tl.to({}, { duration: 0 }, B.duration);
})();
